{
  "lastChangelogVersion": "0.78.3",
  "theme": "pi",
  "defaultProvider": "claude-bridge",
  "defaultModel": "claude-opus-4-8",
  "defaultThinkingLevel": "adaptive",
  "enabledModels": [
    "openai-codex/*",
    "claude-bridge/*"
  ],
  "steeringMode": "all",
  "followUpMode": "all",
  "transport": "auto",
  "hideThinkingBlock": true,
  "sourceUpdateCommand": [
    "/Users/luke/Projects/personal/rusty-terminal-runtime/scripts/update-pi-agent"
  ],
  "extensions": {
    "pi-tool-search": {
      "alwaysActive": [
        "bash",
        "read",
        "edit",
        "write",
        "grep",
        "Agent",
        "skill",
        "skill_search",
        "tool_search",
        "memory_note"
      ]
    }
  },
  "packages": [
    "/Users/luke/Projects/personal/my-pi/packages/my-pi-full",
    "https://github.com/nicobailon/pi-intercom",
    {
      "source": "npm:@howaboua/pi-smart-btw",
      "load": "deferred"
    },
    "git:https://github.com/badlogic/pi-diff-review",
    "git:github.com/kostyay/pi-k-excalidraw",
    "/Users/luke/.pi/agent/local-packages/kilocode-provider",
    "npm:@howaboua/pi-vent",
    {
      "source": "npm:@valkyriweb/pi-codex-conversion",
      "enabledWhen": {
        "models": [
          "openai-codex/*"
        ]
      }
    },
    "npm:pi-assistant-provenance",
    "npm:@plannotator/pi-extension",
    {
      "source": "npm:pi-messenger",
      "load": "deferred"
    },
    "https://github.com/davebcn87/pi-autoresearch"
  ],
  "enableSkillCommands": true,
  "terminal": {
    "showTerminalProgress": true
  },
  "treeFilterMode": "default",
  "warnings": {
    "anthropicExtraUsage": true
  },
  "compaction": {
    "enabled": true,
    "triggerTokens": 350000
  },
  "advisor": {
    "enabled": false
  },
  "cacheHeartbeat": {
    "enabled": false,
    "providers": [
      "openai-codex/",
      "claude-bridge/"
    ],
    "intervalMs": 3300000,
    "workingHours": {
      "start": "06:00",
      "end": "23:00",
      "days": [
        0,
        1,
        2,
        3,
        4,
        5,
        6
      ]
    }
  },
  "extensionConfig": {
    "pi-memory": {
      "recall": {
        "rerank": {
          "enabled": true,
          "modelAlias": "cheap"
        }
      }
    }
  },
  "startup": {
    "deferredExtensionLoadDelayMs": 2000
  },
  "quietStartup": true,
  "doubleEscapeAction": "tree"
}

